/*	Build the daily reconciliation digest from the check-in log.	*/
const cfg_obj = $('Config').item.json;
const lookback_num = Number(cfg_obj.LOOKBACK_HOURS || 24);
const threshold_num = Number(cfg_obj.DUP_THRESHOLD || 0.85);
const title_str = String(cfg_obj.REPORT_TITLE || 'Check-in reconciliation');
const cutoff_num = Date.now() - (lookback_num * 3600 * 1000);

const rows_ary = $input.all().map(function (it_obj) { return it_obj.json; }).filter(function (r_obj) {
	const t_num = Date.parse(r_obj.timestamp || '');
	return !isNaN(t_num) && t_num >= cutoff_num;
});

/*	Plain wording for every reason 3.0 can refuse a scan.	*/
const reasons_obj = {
	'not-open-yet': 'Scanned before check-in opened',
	'closed': 'Scanned after check-in closed',
	'reception-unknown-email': 'Email not recognised, sent to reception',
	'reception-not-booked': 'Not booked on this public course, sent to reception',
	'registration-refused': 'Administrate refused the registration',
	'walk-in-failed': 'Could not set up the walk-in\'s details',
	'attendance-refused': 'Administrate refused the attendance mark',
	'invalid-event': 'QR code for an unknown event',
	'no-sessions': 'Event has no sessions'
};

function reasonFor(mark_str)
{
	const key_str = mark_str.indexOf('blocked-') === 0 ? mark_str.slice(8) : mark_str;
	return reasons_obj[key_str] || key_str;
}

function eventLabel(r_obj)
{
	return String(r_obj.eventTitle || '').trim() || String(r_obj.eventId || '');
}

/*	Group by status.	*/
const byStatus_obj = {};
for (const r_obj of rows_ary)
{
	const s_str = String(r_obj.status || 'unknown');
	byStatus_obj[s_str] = (byStatus_obj[s_str] || 0) + 1;
}

/*	Group by attendance mark. 'Present' means Administrate accepted the mark; anything beginning	*/
/*	'blocked-' means the scan happened but no attendance was recorded, and why.	*/
const byMark_obj = {};
for (const r_obj of rows_ary)
{
	const mark_str = String(r_obj.attendanceMark || 'unknown');
	const label_str = mark_str === 'Present' ? 'Present' : reasonFor(mark_str);
	byMark_obj[label_str] = (byMark_obj[label_str] || 0) + 1;
}

/*	Rows needing review. Includes needs-review-multiple-contact, where one email matched several	*/
/*	contacts and check-in took the first.	*/
const needsReview_ary = rows_ary.filter(function (r_obj) { return String(r_obj.status || '').indexOf('needs-review') === 0; });

/*	Every scan Administrate did not record. This is the section that matters on the day. 3.0 writes	*/
/*	exactly 'Present' for a recorded check-in and 'blocked-<reason>' for everything else.	*/
const notRecorded_ary = rows_ary.filter(function (r_obj) { return String(r_obj.attendanceMark || '') !== 'Present'; });

/*	Fuzzy duplicate detection on normalized full names (Levenshtein similarity).	*/
function norm(v_var)
{
	return String(v_var || '').toLowerCase().replace(/[^a-z0-9 ]/g, '').replace(/\s+/g, ' ').trim();
}

function levenshtein(a_str, b_str)
{
	const m_num = a_str.length;
	const n_num = b_str.length;
	if (m_num === 0) { return n_num; }
	if (n_num === 0) { return m_num; }
	const d_ary = [];
	for (let i_num = 0; i_num <= m_num; i_num++) { d_ary[i_num] = [i_num]; }
	for (let j_num = 0; j_num <= n_num; j_num++) { d_ary[0][j_num] = j_num; }
	for (let i_num = 1; i_num <= m_num; i_num++)
	{
		for (let j_num = 1; j_num <= n_num; j_num++)
		{
			const cost_num = a_str[i_num - 1] === b_str[j_num - 1] ? 0 : 1;
			d_ary[i_num][j_num] = Math.min(d_ary[i_num - 1][j_num] + 1, d_ary[i_num][j_num - 1] + 1, d_ary[i_num - 1][j_num - 1] + cost_num);
		}
	}
	return d_ary[m_num][n_num];
}

function similarity(a_str, b_str)
{
	const max_num = Math.max(a_str.length, b_str.length);
	return max_num === 0 ? 1 : (1 - (levenshtein(a_str, b_str) / max_num));
}

/*	One entry per person (dedupe by email) so repeat scans do not double-count pairs.	*/
const seenEmails_obj = {};
const people_ary = [];
for (const r_obj of rows_ary)
{
	const name_str = norm(String(r_obj.firstName || '') + ' ' + String(r_obj.lastName || ''));
	const emailKey_str = String(r_obj.email || '').toLowerCase();
	if (name_str === '') { continue; }
	if (emailKey_str !== '' && seenEmails_obj[emailKey_str]) { continue; }
	if (emailKey_str !== '') { seenEmails_obj[emailKey_str] = true; }
	people_ary.push({ name: name_str, email: emailKey_str, raw: r_obj });
}

const dupes_ary = [];
for (let i_num = 0; i_num < people_ary.length; i_num++)
{
	for (let j_num = i_num + 1; j_num < people_ary.length; j_num++)
	{
		const a_obj = people_ary[i_num];
		const b_obj = people_ary[j_num];
		if (a_obj.email === b_obj.email) { continue; }
		const score_num = similarity(a_obj.name, b_obj.name);
		if (score_num >= threshold_num)
		{
			dupes_ary.push({ a: a_obj, b: b_obj, score: score_num });
		}
	}
}

function esc(v_var) { return String(v_var == null ? '' : v_var).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;'); }

const tableOpen_str = '<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">';

let html_str = '<h2>' + esc(title_str) + ' - last ' + lookback_num + 'h</h2>';
html_str += '<p>Total scans: <strong>' + rows_ary.length + '</strong></p>';

html_str += '<h3>By status</h3><ul>';
for (const s_str of Object.keys(byStatus_obj).sort())
{
	html_str += '<li>' + esc(s_str) + ': ' + byStatus_obj[s_str] + '</li>';
}
html_str += '</ul>';

html_str += '<h3>By result</h3><ul>';
for (const m_str of Object.keys(byMark_obj).sort())
{
	html_str += '<li>' + esc(m_str) + ': ' + byMark_obj[m_str] + '</li>';
}
html_str += '</ul>';

html_str += '<h3>Attendance not recorded (' + notRecorded_ary.length + ')</h3>';
if (notRecorded_ary.length === 0)
{
	html_str += '<p>None - every scan was marked in Administrate.</p>';
} else {
	html_str += tableOpen_str + '<tr><th>Email</th><th>Name</th><th>Event</th><th>Session</th><th>Reason</th></tr>';
	for (const r_obj of notRecorded_ary)
	{
		html_str += '<tr><td>' + esc(r_obj.email) + '</td><td>' + esc(r_obj.firstName) + ' ' + esc(r_obj.lastName) + '</td><td>' + esc(eventLabel(r_obj)) + '</td><td>' + esc(r_obj.sessionId) + '</td><td>' + esc(reasonFor(String(r_obj.attendanceMark || 'unknown'))) + '</td></tr>';
	}
	html_str += '</table>';
}

html_str += '<h3>Needs review (' + needsReview_ary.length + ')</h3>';
if (needsReview_ary.length === 0)
{
	html_str += '<p>None - nothing to reconcile.</p>';
} else {
	html_str += tableOpen_str + '<tr><th>Email</th><th>Name</th><th>Company</th><th>Status</th><th>Contact</th><th>Event</th></tr>';
	for (const r_obj of needsReview_ary)
	{
		html_str += '<tr><td>' + esc(r_obj.email) + '</td><td>' + esc(r_obj.firstName) + ' ' + esc(r_obj.lastName) + '</td><td>' + esc(r_obj.company) + '</td><td>' + esc(r_obj.status) + '</td><td>' + esc(r_obj.contactId) + '</td><td>' + esc(eventLabel(r_obj)) + '</td></tr>';
	}
	html_str += '</table>';
}

html_str += '<h3>Possible duplicates (' + dupes_ary.length + ', threshold ' + Math.round(threshold_num * 100) + '%)</h3>';
if (dupes_ary.length === 0)
{
	html_str += '<p>None detected.</p>';
} else {
	html_str += tableOpen_str + '<tr><th>Match</th><th>Person A</th><th>Person B</th></tr>';
	for (const d_obj of dupes_ary)
	{
		html_str += '<tr><td>' + Math.round(d_obj.score * 100) + '%</td><td>' + esc(d_obj.a.raw.firstName) + ' ' + esc(d_obj.a.raw.lastName) + ' (' + esc(d_obj.a.email) + ')</td><td>' + esc(d_obj.b.raw.firstName) + ' ' + esc(d_obj.b.raw.lastName) + ' (' + esc(d_obj.b.email) + ')</td></tr>';
	}
	html_str += '</table>';
}

const subject_str = title_str + ' - ' + rows_ary.length + ' scans, ' + notRecorded_ary.length + ' unmarked, ' + needsReview_ary.length + ' to review, ' + dupes_ary.length + ' possible dupes';

return [{ json: { subject: subject_str, html: html_str, total: rows_ary.length, notRecorded: notRecorded_ary.length, needsReview: needsReview_ary.length, dupes: dupes_ary.length } }];
